ALTER TABLE "payment_customers" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "customer_owner_read" ON "payment_customers" AS PERMISSIVE FOR SELECT TO public USING ("payment_customers"."source"=current_setting('rove.customer_source',true) AND "payment_customers"."rider_id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND current_setting('rove.actor_role',true)='rider' AND EXISTS(SELECT 1 FROM public.users u WHERE u.id="payment_customers"."rider_id" AND u.role='rider' AND u.disabled=false));--> statement-breakpoint
CREATE POLICY "customer_owner_reserve" ON "payment_customers" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("payment_customers"."customer_id" IS NULL AND "payment_customers"."source"=current_setting('rove.customer_source',true) AND "payment_customers"."rider_id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND current_setting('rove.actor_role',true)='rider' AND EXISTS(SELECT 1 FROM public.users u WHERE u.id="payment_customers"."rider_id" AND u.role='rider' AND u.disabled=false));--> statement-breakpoint
CREATE POLICY "customer_worker_read" ON "payment_customers" AS PERMISSIVE FOR SELECT TO public USING ("payment_customers"."source"=current_setting('rove.customer_source',true) AND ("payment_customers"."id"=NULLIF(current_setting('rove.customer_read',true),'')::uuid OR "payment_customers"."id"=NULLIF(current_setting('rove.customer_write',true),'')::uuid));--> statement-breakpoint
CREATE POLICY "customer_result_update" ON "payment_customers" AS PERMISSIVE FOR UPDATE TO public USING ("payment_customers"."source"=current_setting('rove.customer_source',true) AND "payment_customers"."id"=NULLIF(current_setting('rove.customer_write',true),'')::uuid AND ("payment_customers"."customer_id" IS NULL OR "payment_customers"."customer_id"=NULLIF(current_setting('rove.customer_result',true),''))) WITH CHECK ("payment_customers"."source"=current_setting('rove.customer_source',true) AND "payment_customers"."id"=NULLIF(current_setting('rove.customer_write',true),'')::uuid AND "payment_customers"."customer_id"=NULLIF(current_setting('rove.customer_result',true),''));
--> statement-breakpoint
ALTER TABLE "payment_customers" FORCE ROW LEVEL SECURITY;
